update_md5_ccbf61c9d1dd1b62130a910f6900e.content_md5_ccbf61c9d1dd1b62130a910f6900:
useInput((inputChar: string, key: Key) => {
  if (process.env.GROK_DEBUG_INPUT) {
    const seq = typeof key.sequence === "string" ? key.sequence : "";
    const escapedSeq = seq
      .replaceAll("\r", "\\r")
      .replaceAll("\n", "\\n")
      .replaceAll("\t", "\\t")
      .replaceAll("\u001b", "\\x1b");

    setLastKeyDebug(
      `inputChar=${JSON.stringify(inputChar)} seq=${JSON.stringify(escapedSeq)} name=${String(key.name ?? "")} ctrl=${!!key.ctrl} meta=${!!key.meta} shift=${!!key.shift}`
    );
  }

  handleInput(inputChar, key);
});
